import{_ as t,o,c as i,a0 as a}from"./chunks/framework.BSa2j5Vp.js";const u=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compatibility.md","filePath":"guide/compatibility.md"}'),n={name:"guide/compatibility.md"};function d(r,e,s,c,l,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><p>Supported means probed, not declared. Every version below has live evidence behind it — catalog listing, real text turns, rewind/fork, approval flows — recorded in the repo&#39;s <a href="https://github.com/pgquiles/opencode-muse/blob/main/docs/compatibility.md" target="_blank" rel="noreferrer">compatibility record</a>, which also holds the full schema-snapshot ledger. This page summarizes; the record rules.</p><h2 id="current-pins" tabindex="-1">Current pins <a class="header-anchor" href="#current-pins" aria-label="Permalink to &quot;Current pins&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Status</th></tr></thead><tbody><tr><td>Muse CLI</td><td><code>1.4.14</code> exact pin (SDK fingerprint matches, no warning); <code>1.4.20</code> verified under the recorded fingerprint warning</td></tr><tr><td><code>@muse-code/sdk</code></td><td><code>1.4.14</code></td></tr><tr><td>OpenCode</td><td><code>2.1.4</code> verified target; <code>2.3.0</code> in active use</td></tr><tr><td>OpenChamber embedded OpenCode</td><td><code>2.0.32</code> (smoke-tested)</td></tr></tbody></table><p>A served CLI fingerprint that differs from the SDK pin does not block startup — the host records a <code>fingerprintWarning</code> and continues. Only a missing/malformed fingerprint or a different envelope version fails closed.</p><h2 id="which-combinations-work" tabindex="-1">Which combinations work <a class="header-anchor" href="#which-combinations-work" aria-label="Permalink to &quot;Which combinations work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Muse CLI</th><th>Default backend (<code>muse</code>)</th><th>Opt-in backend (<code>opencode</code>)</th></tr></thead><tbody><tr><td>1.4.12 – 1.4.14</td><td>Verified</td><td>Verified on 1.4.14</td></tr><tr><td>1.4.20</td><td>Verified (fingerprint warning)</td><td>Blocked — setup fails naming <a href="https://github.com/pgquiles/opencode-muse/issues/58" target="_blank" rel="noreferrer">#58</a></td></tr><tr><td>Other 1.x (envelope v1)</td><td>Starts with warning, unverified</td><td>Blocked until a backend live-turn probe passes</td></tr></tbody></table><p>On the OpenCode side the verified range is 2.0.32 (embedded) through 2.3.0 for both backends; outside it the plugin starts but is untested. When in doubt, the default backend on a verified CLI is the combination with live evidence behind it.</p><h2 id="known-1-4-20-limitation-opencode-tool-backend" tabindex="-1">Known 1.4.20 limitation: opencode tool backend <a class="header-anchor" href="#known-1-4-20-limitation-opencode-tool-backend" aria-label="Permalink to &quot;Known 1.4.20 limitation: opencode tool backend&quot;">​</a></h2><p>Muse CLI 1.4.20 rejects session MCP servers in <code>run.toolset</code> (<code>configError: unknown tool</code>), and without the pin MCP tools never load into the run. The opencode backend therefore fails setup fast with a clear error on 1.4.20. The default muse backend is unaffected on all verified CLIs. Tracked upstream; the backend re-opens per CLI version once a backend live-turn probe passes.</p><h2 id="what-verified-costs" tabindex="-1">What &quot;verified&quot; costs <a class="header-anchor" href="#what-verified-costs" aria-label="Permalink to &quot;What &quot;verified&quot; costs&quot;">​</a></h2><p>Adding a version means: offline schema export, snapshot + additive-delta classification, catalog and text-turn probes on each billing path in use, an explicit-cut fork probe, and (for the opencode backend) a live tool turn. No export is ever committed — only the snapshot ledger.</p>',12)])])}const b=t(n,[["render",d]]);export{u as __pageData,b as default};
